"""
  Replaces all negative values with default_value

  :param l: Original list
  :param default_value: The value to replace negatives values with. Default is 0.
  :return: Number of values replaced
  """
def replace_negative(l: Any, default_value: Any = 0) -> object {
    n_replaced = 0;
    for i in range(len(l)) {
        if (l[i] < 0) {
            l[i] = default_value;
            n_replaced += 1;
        }
    }
    return n_replaced;
}

"""Try to make an ASCII representation of the bytes.

    Non printable characters are replaced by '?' except null character which
    is replaced by '.'.
    """
def format_data_ascii(data: Any) -> object {
    msg_str = '';
    for byte in data {
        char = chr(byte);
        if (char == '\0') {
            msg_str = msg_str + '.';
        } elif ((ord(char) < 32) or (ord(char) > 126)) {
            msg_str = msg_str + '?';
        } else {
            msg_str = msg_str + char;
        }
    }
    return msg_str;
}

