""" Shuffles two elements, indicated by `idx1` and `idx2`, between
    two datasets in `dataset_dict`.
    """
def shuffle_datasets(
    dataset_dict: Any, dataset_names: Any, idx1: Any, idx2: Any
) -> object {
    for name in dataset_names {
        (dataset_dict[name][idx1], dataset_dict[name][idx2]) = (
            dataset_dict[name][idx2],
            dataset_dict[name][idx1]
        );
    }
    return dataset_dict;
}

"""Sum even Fib numbers below 'limit'"""
def evenFibSum(limit: Any) -> object {
    sum = 0;
    (a, b) = (1, 2);
    while (b < limit) {
        if ((b % 2) == 0) {
            sum += b;
        }
        (a, b) = (b, (a + b));
    }
    return sum;
}

